 mount.innerHTML=`<h2>${images?'Your images, a little more organized.':merge?'Bring your documents together.':'Just the pages you need.'}</h2>${uploadHTML(accept,images||merge,images?'Choose images for your PDF':merge?'Choose two or more PDFs':'Choose a PDF',images?'Images up to 25 MB each · 60 MB combined':'PDF files · up to 60 MB combined')}<ol class="file-list"></ol><form><div class="form-grid">${fields.map(field).join('')}</div><p class="form-note">${images||merge?'Files appear in selection order. Use the arrows to reorder them before creating your PDF.':'Use page numbers or ranges: 1, 3-5, 8. Output follows the order you enter. Password-protected PDFs are not supported.'}</p><div class="form-actions"><button class="btn primary" type="submit" disabled>${images?'Create PDF':merge?'Merge PDFs':'Extract pages'} ${icon('arrow')}</button><button class="btn secondary" type="button" data-clear>Clear files</button></div><div class="media-error"></div></form>`;
 const list=mount.querySelector('.file-list'),f=mount.querySelector('form'),button=f.querySelector('[type=submit]'),err=mount.querySelector('.media-error');
